import {CLIMATE_LAYERS} from './weather-labels.js';
import {CITIES,normalizeCity} from './places.js';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mark='<span class="lente-mark" aria-hidden="true"><i></i></span>';
export const lenteRichText=text=>escape(text).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
const labels={weather:'Meteo',globe:'Globo',map:'Mappa',community:'Community'};
const layerLabels=Object.fromEntries(CLIMATE_LAYERS.map(l=>[l.id,l.label]));
export function lenteKey(c){return [c.section,c.latitude??'',c.longitude??'',c.city,c.layer||'',c.postId||''].join('|')}
export function createLente(ctx){
 const personas=[['neutral','Essenziale'],['arcade','Arcade'],['premuroso','Premuroso'],['cynic','Cinico']];let persona='neutral';try{const p=localStorage.getItem('ms-lente-persona');if(personas.some(([id])=>id===p))persona=p}catch{}
 const sessions=new Map();let active=null,pageSection='weather',dialog=null,lastRoute='',returnFocus=null,resume=null;
 try{const saved=JSON.parse(sessionStorage.getItem('ms-lente-login')||'null');sessionStorage.removeItem('ms-lente-login');if(saved&&Date.now()-saved.at<900000&&saved.context&&typeof saved.draft==='string'){resume=saved;session(saved.context).draft=saved.draft}}catch{}
 const announcer=document.createElement('div');announcer.className='lente-sr-only';announcer.setAttribute('role','status');announcer.setAttribute('aria-live','polite');document.body.append(announcer);
 const sectionFromRoute=()=>({home:'weather',mondo:'globe',mappa:'map',radar:'map',community:'community',stories:'community',tendenze:'weather'}[ctx.get().route]||'weather');
 function context(options={}){
  const p=ctx.get().place;let loc={...p};
  if(options.city&&normalizeCity(options.city)!==normalizeCity(p.name)){
   const match=CITIES.find(c=>normalizeCity(c.name)===normalizeCity(options.city));loc=match||{name:options.city,latitude:null,longitude:null};
  }
  return {section:options.section||sectionFromRoute(),city:options.city||loc.name,latitude:loc.latitude,longitude:loc.longitude,layer:options.layer||'meteo',postId:options.postId||'',postTitle:options.postTitle||''};
 }
 function session(c){const key=lenteKey(c);if(!sessions.has(key)){sessions.set(key,{context:c,draft:'',messages:[],busy:false,error:'',pendingQuestion:'',token:0});if(sessions.size>16){const candidate=[...sessions.keys()].find(k=>k!==active&&!sessions.get(k).busy);if(candidate)sessions.delete(candidate)}}return sessions.get(key)}
 function current(){return active?sessions.get(active):null}
 function choices(c){
  if(c.section==='community'&&c.layer==='grandine')return [['Cosa sappiamo','Riassumi le segnalazioni di grandine nelle ultime due ore, distinguendole da previsioni e bollettini. Non analizzare foto o radar.','hail'],['Cosa manca','Quali dati mancano per capire se la grandine arriverà qui? Non inventare tempi o percentuali.','missing'],['Chiedi un dettaglio','Prepara una domanda gentile per chiarire luogo dichiarato e ora di un post, senza chiedere indirizzi privati o nuove riprese al maltempo.','question']];
  if(c.postId)return [['Leggi il post','Distingui ciò che questo post racconta, ciò che non dimostra e cosa sarebbe utile chiedere all’autore.','post'],['Una risposta gentile','Prepara una breve risposta utile e gentile a questo post, senza inventare fatti.','reply'],['Titolo da condividere','Proponi un titolo breve per questo post, fedele al testo e senza allarmismi.','caption']];
  if(c.section==='community')return [['La voce della zona','Riassumi i testi dei post recenti di questa località. Se sono pochi, dichiaralo.','community'],['Previsioni e persone','Confronta le previsioni disponibili con i testi dei post recenti. Non trattare le segnalazioni come fatti verificati.','compare'],['Chiedilo alla community','Prepara una domanda breve e utile da fare alla community sul meteo di questa località.','question']];
  if(c.section==='map')return [[c.layer==='grandine'?'Capire la grandine':'Leggi questo livello','Spiegami come leggere il livello '+(layerLabels[c.layer]||'Meteo')+' della mappa. Chiarisci cosa non posso dedurre.','map'],['Pioggia nelle prossime ore','Come cambia la probabilità di pioggia nelle prossime 24 ore?','rain'],['Prima di cercare copertura','Quali informazioni devo verificare prima di scegliere un luogo coperto? Non inventare posti o disponibilità.','shelter']];
  if(c.section==='globe')return [['Questa città in breve','Riassumi il meteo della località selezionata e cosa cambia domani.','globe'],['La tendenza','Come cambiano temperatura e pioggia nei prossimi sette giorni?','trend'],['Cosa guardare','Spiegami cosa mostrano i simboli e i livelli del globo di MeteoSocial.','guide']];
  return [['Porto l’ombrello?','Mi serve l’ombrello nelle prossime 24 ore? Indica gli orari locali più interessanti e l’incertezza.','rain'],['Quando esco?','Confronta le prossime ore per una passeggiata, considerando pioggia, vento e temperatura. Non garantire sicurezza.','outing'],['Il cielo in una frase','Scrivi una frase originale e leggera sul meteo di questa località, senza inventare dati e senza minimizzare eventuali pericoli.','creative']];
 }
 function orbit(size=''){return `<div class="lente-orbit ${size}" aria-hidden="true"><div class="lente-orbit-ring"></div><div class="lente-orbit-ring second"></div><div class="lente-core"></div><span class="lente-satellite"></span></div>`}
 function weatherStamp(c){const p=ctx.get().place,w=ctx.get().weather;if(!w||c.latitude!==p.latitude||c.longitude!==p.longitude)return '';const t=w.current?.temperature_2m;return Number.isFinite(t)?`<span class="lente-temperature">${Math.round(t)}°<small>Open-Meteo</small></span>`:''}
 function chip(c){return `<span class="lente-context-chip">⌖ ${escape(c.city)}</span><span class="lente-context-chip">${escape(labels[c.section])}${['map','globe'].includes(c.section)&&c.layer!=='meteo'?' · '+escape(layerLabels[c.layer]):''}</span>`}
 function privacy(c){if(c.section==='community'&&c.layer==='grandine')return 'Alla richiesta vengono inviati a OpenAI località, previsioni, bollettino e fino a 12 segnalazioni: testi, orari, dimensioni dichiarate, fine riferita e conteggi dei riscontri. Coordinate, foto, video e nomi degli autori sono esclusi.';return c.section==='community'?'Alla richiesta vengono inviati a OpenAI il testo dei post pubblici selezionati e le previsioni disponibili. Foto, video e nomi degli autori sono esclusi.':'Alla richiesta vengono inviati a OpenAI la località scelta e i dati delle previsioni. Nessuna analisi dei pixel radar.'}
 function sourceCards(m){if(!m.sources?.length)return '';return `<details class="lente-sources"><summary>Da dove arriva questa risposta <span>${m.sources.length}</span></summary>${m.sources.map(s=>s.type==='official'?`<div><span class="lente-source-tag">BOLLETTINO UFFICIALE</span><strong>${escape(s.label)}</strong><p>${escape(s.at)} · ${escape(s.zone)}</p><a href="https://github.com/pcm-dpc/DPC-Bollettini-Criticita-Idrogeologica-Idraulica" target="_blank" rel="noopener">Protezione Civile ↗</a></div>`:s.type==='weather'?`<div><span class="lente-source-tag">PREVISIONE</span><strong>${escape(s.label)}</strong><p>${escape(s.at?.replace('T',' '))} · ${escape(s.timezone||'')}<br>${Number(s.hours)||0} ore · ${Number(s.days)||0} giorni</p></div>`:`<div><span class="lente-source-tag community">COMMUNITY</span><strong>${Number(s.count)||0} ${Number(s.count)===1?'testo':'testi'} nel campione</strong><p>Ultime ${s.windowHours===2?2:24} ore · osservazioni non verificate.</p>${(s.items||[]).map((p,i)=>`<a href="#post:${encodeURIComponent(p.id)}">Post ${i+1} · ${escape(p.city)} · ${escape(p.kind)} ↗</a>`).join('')}</div>`).join('')}${(m.notes||[]).map(n=>`<p>${escape(n)}</p>`).join('')}</details>`}
 function messages(s){return s.messages.map((m,i)=>m.role==='user'?`<div class="lente-message user"><span>Tu</span><p>${escape(m.text)}</p></div>`:`<article class="lente-message answer"><div class="lente-answer-signature">${mark}<b>Lente</b><span>IA · ${escape(s.context.city)}</span></div><div class="lente-answer-copy">${lenteRichText(m.text)}</div>${sourceCards(m)}${m.safety==='EMERGENCY'?'<div class="lente-safety-actions"><a href="https://rischi.protezionecivile.gov.it/it/meteo-idro/" target="_blank" rel="noopener">Indicazioni ufficiali ↗</a><a href="#stanza">Apri la stanza meteo →</a></div>':''}<div class="lente-answer-actions"><button data-lente-copy="${i}" aria-label="Copia la risposta di Lente">Copia risposta</button><button data-lente-more="${i}">Spiegamelo meglio</button></div></article>`).join('')+(s.busy?`<div class="lente-thinking" role="status">${mark}<span>Lente sta leggendo i dati<span class="lente-loading-dots" aria-hidden="true">…</span></span></div>`:'')}
 function composer(s,compact){const ready=ctx.get().aiReady,id=compact?'lente-sheet-question':'lente-question';return `<form class="lente-composer" data-lente-form><label for="${id}">${s.messages.length?'Continuiamo da qui':'Cosa vuoi sapere?'}</label><div class="lente-input-row"><textarea id="${id}" data-lente-draft ${s.busy?'disabled':''} rows="2" maxlength="1500" required placeholder="Chiedimi del cielo, della zona, della giornata…">${escape(s.draft)}</textarea><button class="lente-send" ${s.busy||!ready?'disabled':''} aria-label="Invia a Lente"><span aria-hidden="true">↑</span><span class="lente-send-label">Invia</span></button></div><div class="lente-composer-foot"><span>${!ready?'Collegamento IA non disponibile':ctx.get().me?'Solo quando lo chiedi tu':'Accedi con ChatGPT per chiedere a Lente'}</span><span>${s.messages.length?'Puoi fare una domanda di seguito':'Invio manuale'}</span></div></form><p class="lente-data-note">${privacy(s.context)}</p>${s.error?`<div class="lente-error" role="alert">${escape(s.error)} <button data-lente-retry ${s.busy?'disabled':''}>Riprova</button></div>`:''}`}
 function body(s,compact=false){return `<div class="lente-session" data-lente-session="${escape(lenteKey(s.context))}">${s.context.postTitle?`<div class="lente-post-context"><span>STAI LEGGENDO QUESTO POST</span><p>${escape(s.context.postTitle)}</p></div>`:''}${s.messages.length||s.busy?`<div class="lente-conversation" aria-label="Conversazione con Lente">${messages(s)}</div>`:''}<span class="lente-personas-label">La voce di Lente · sempre seria in caso di pericolo</span><div class="lente-personas" aria-label="Personalità di Lente">${personas.map(([id,label])=>`<button data-lente-persona="${id}" aria-pressed="${id===persona}" ${s.busy?'disabled':''}>${label}</button>`).join('')}</div>${composer(s,compact)}<div class="lente-prompts ${compact?'compact':''}" aria-label="Domande suggerite">${choices(s.context).map(([title,q,icon],i)=>`<button data-lente-prompt="${escape(q)}" ${s.busy?'disabled':''}><span class="lente-prompt-number">0${i+1}</span><span>${escape(title)}</span><span aria-hidden="true">↗</span></button>`).join('')}</div><details class="lente-disclosure"><summary>Cosa legge Lente?</summary><p>${privacy(s.context)} Le ultime tre domande e risposte possono dare continuità alla conversazione. Non invia coordinate GPS a OpenAI. Le risposte possono contenere errori. Le allerte vanno verificate sulle fonti ufficiali.</p></details></div>`}
 function page(){const c=context({section:pageSection}),key=lenteKey(c);if(!dialog?.open)active=key;const s=session(c);return `<section class="lente-page"><div class="lente-page-top"><div class="lente-wordmark">${mark}<span>Lente <b>IA</b></span></div><button class="lente-reset" data-lente-clear ${s.busy?'disabled':''}>Nuova conversazione</button></div><div class="lente-hero"><div><div class="lente-eyebrow">METEOSOCIAL INTELLIGENCE</div><h1>Il tuo cielo.<br><em>Un po’ più chiaro.</em></h1><p>Le domande sono tue.<br>Il punto di partenza è qui.</p><div class="lente-context-row">${chip(c)}</div></div><div class="lente-hero-art"><img class="cielo-lente-art" src="/assets/cielo-atmosphere.webp" alt="" width="1774" height="887">${weatherStamp(c)}<span class="lente-art-caption">ILLUSTRAZIONE · DATI DELLA ZONA</span></div></div><div class="lente-modebar" aria-label="Contesto dell’assistente">${Object.entries(labels).map(([id,label])=>`<button data-lente-section="${id}" aria-pressed="${id===pageSection}">${label}</button>`).join('')}</div><div class="lente-page-workspace">${body(s)}<aside class="lente-side-note"><span class="lente-side-number">01—04</span><h2>Un’unica lente.<br>Quattro prospettive.</h2><p>Previsioni, luoghi e racconti. Con le fonti sempre a portata di mano.</p><div class="lente-route-list"><a href="#mondo">Esplora i luoghi <span>↗</span></a><a href="#mappa">Guarda la mappa <span>↗</span></a><a href="#tendenze">Leggi le previsioni <span>↗</span></a><a href="#community">Ascolta la community <span>↗</span></a></div><p class="lente-small-note">Lente spiega e prepara bozze.<br>Pubblicare resta una tua scelta.</p></aside></div></section>`}
 function entry(section,options={}){return `<button class="lente-entry ${options.small?'small':''}" data-lente-entry="${section}" ${options.layer?`data-lente-layer="${escape(options.layer)}"`:''} ${options.city?`data-lente-city="${escape(options.city)}"`:''}>${mark}<span><b>${options.label||'Guardalo con Lente'}</b>${options.small?'':`<small>${options.description||'La tua zona, spiegata dall’IA'}</small>`}</span><span class="lente-entry-arrow" aria-hidden="true">↗</span></button>`}
 function open(options={},question=''){
  const c=context(options);active=lenteKey(c);const s=session(c);if(question)s.draft=question;
  if(!dialog){dialog=document.createElement('dialog');dialog.className='lente-sheet';dialog.setAttribute('aria-labelledby','lente-sheet-title');document.body.append(dialog);dialog.addEventListener('close',()=>{if(ctx.get().route==='assistente')active=lenteKey(context({section:pageSection}));if(returnFocus?.isConnected)returnFocus.focus();returnFocus=null})}
  returnFocus=document.activeElement;paintSheet();if(!dialog.open)dialog.showModal();dialog.querySelector('[data-lente-draft]')?.focus({preventScroll:true});
 }
 function paintSheet(){const s=current();if(!s||!dialog)return;dialog.innerHTML=`<div class="lente-sheet-top"><div class="lente-wordmark">${mark}<span id="lente-sheet-title">Lente <b>IA</b></span></div><button data-lente-close aria-label="Chiudi Lente">×</button></div><div class="lente-sheet-heading"><div><span class="lente-eyebrow">DENTRO LA TUA ZONA</span><h2>${escape(s.context.city)}</h2><span>${escape(labels[s.context.section])}${['map','globe'].includes(s.context.section)&&s.context.layer!=='meteo'?' · '+escape(layerLabels[s.context.layer]):''}</span></div>${orbit('small')}</div><div class="lente-sheet-body">${body(s,true)}</div>`}
 function redraw(){if(dialog?.open)paintSheet();else if(ctx.get().route==='assistente')ctx.render()}
 async function send(){const s=current();if(!s||s.busy)return;const question=s.draft.trim();if(!question||!ctx.get().aiReady)return;
  if(!ctx.get().me){s.error='Accedi per chiedere a Lente. La domanda rimane qui.';try{sessionStorage.setItem('ms-lente-login',JSON.stringify({at:Date.now(),context:s.context,draft:question}))}catch{}if(dialog?.open)dialog.close();ctx.login();return}
  const key=lenteKey(s.context),token=++s.token,history=s.messages.slice(-6).map(m=>({role:m.role,text:m.text}));s.busy=true;s.error='';announcer.textContent='Lente sta preparando la risposta.';s.pendingQuestion=question;s.messages.push({role:'user',text:question});s.draft='';redraw();
  try{const result=await ctx.ask({question,context:{...s.context},history,persona});if(token!==s.token)return;s.messages.push({role:'assistant',text:result.answer,sources:result.sources||[],notes:result.notes||[],safety:result.safety});s.pendingQuestion='';announcer.textContent='Risposta disponibile per '+s.context.city+'.'}catch(e){if(token!==s.token)return;if(s.messages.at(-1)?.role==='user')s.messages.pop();s.draft=question;s.error=e.message||'Non è arrivata una risposta. Riprova.';announcer.textContent=s.error}finally{if(token===s.token)s.busy=false;if(active===key)redraw()}
 }
 function sync(){const route=ctx.get().route;if(lastRoute&&route!==lastRoute&&dialog?.open)dialog.close();lastRoute=route;if(resume&&ctx.get().me){const saved=resume;resume=null;queueMicrotask(()=>open(saved.context,saved.draft))}}
 document.addEventListener('input',e=>{if(e.target.matches('[data-lente-draft]')){const s=current();if(s)s.draft=e.target.value}});
 document.addEventListener('submit',e=>{if(e.target.matches('[data-lente-form]')){e.preventDefault();send()}});
 document.addEventListener('click',async e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.hasAttribute('data-lente-entry')){open({section:b.dataset.lenteEntry,layer:b.dataset.lenteLayer,city:b.dataset.lenteCity});return}
  if(b.hasAttribute('data-lente-persona')){if(current()?.busy)return;persona=b.dataset.lentePersona;try{localStorage.setItem('ms-lente-persona',persona)}catch{}redraw();return}
  if(b.hasAttribute('data-lente-close')){dialog?.close();return}
  if(b.hasAttribute('data-lente-section')){pageSection=b.dataset.lenteSection;ctx.render();return}
  if(b.hasAttribute('data-lente-prompt')){const s=current();if(!s||s.busy)return;s.draft=b.dataset.lentePrompt;redraw();document.querySelector('[data-lente-draft]')?.focus();return}
  if(b.hasAttribute('data-lente-clear')){const s=current();if(!s||s.busy)return;s.messages=[];s.draft='';s.error='';redraw();return}
  if(b.hasAttribute('data-lente-retry')){send();return}
  if(b.hasAttribute('data-lente-more')){const s=current();if(!s||s.busy)return;s.draft='Spiegami meglio la tua ultima risposta, con un esempio semplice.';redraw();return}
  if(b.hasAttribute('data-lente-copy')){const m=current()?.messages[Number(b.dataset.lenteCopy)];if(!m)return;try{await navigator.clipboard.writeText(m.text+'\n\nLente IA · MeteoSocial · '+current().context.city+'\nRisposta generata con IA. Verifica le fonti.');ctx.toast('Risposta copiata.')}catch{ctx.toast('Copia non disponibile: puoi selezionare il testo della risposta.')}}
 });
 function refreshWeather(){const art=document.querySelector('.lente-hero-art');if(!art)return;art.querySelector('.lente-temperature')?.remove();art.insertAdjacentHTML('beforeend',weatherStamp(context({section:pageSection})))}
 return {page,entry,open,sync,refreshWeather};
}
